fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // The problem guarantees arr1.len() == arr2.len() and arr2 contains no zeros.
    let len = arr1.len();
    assert_eq!(len, arr2.len(), "Input arrays must have the same length");

    let mut result = Vec::with_capacity(len);
    for (&num, &den) in arr1.iter().zip(arr2.iter()) {
        // Safe to divide because den != 0 and quotient fits in u32 by assumption.
        result.push(num / den);
    }

    result
}

